#include <iostream>
using std::cout;
using std::endl;

int main()
{
    int arr[6] = { 3, 7, 1, 9, 4, 6 };
    int* p = arr;
    int sum = 0;
    int max = *p;

    for (int i = 0; i < 6; i++)
    {
        sum += *p;
        if (*p > max)
        {
            max = *p;
        }
        p++;
    }

    cout << "합계: " << sum << endl;
    cout << "최댓값: " << max << endl;

    return 0;
}

